    #[Test]
    public function non_system_admin_cannot_lock_event_operations_route(): void
    {
        [$organizer] = $this->adminWithPlan(PlanTier::GROWTH);
        $event = $this->eventFor($organizer, EventState::DRAFT);
        $sameTeamAdmin = User::factory()->create([
            'email_verified_at' => now(),
            'current_team_id' => $organizer->currentTeam->id,
        ]);
        $organizer->currentTeam->users()->attach($sameTeamAdmin, ['role' => UserRole::ADMIN->value]);

        $this->actingAs($sameTeamAdmin)
            ->post(route('admin.events.lock-publishing', $event->uuid), ['reason' => 'No access'])
            ->assertForbidden();

        $this->assertFalse(app(EventOperationalLockService::class)->active($event, EventOperationalLockKey::PUBLISH));
        $this->assertSame(0, DB::table('activity_log')->where('log_name', 'event.operational_lock')->count());
    }

    #[Test]
    public function global_event_viewer_sees_lock_state_without_mutation_controls(): void
    {
        [$organizer] = $this->adminWithPlan(PlanTier::GROWTH);
        $event = $this->eventFor($organizer, EventState::READY);
        $operator = $this->createPlatformSuperAdmin($organizer->currentTeam);
        $viewerRole = Role::query()->create([
            'name' => 'Global Event Viewer',
            'key' => 'global-event-viewer-test',
            'description' => 'Test-only system role with global event view access but no operation lock controls.',
            'is_system_role' => false,
            'is_system_admin' => true,
        ]);
        $viewerRole->assignPermission('events.view.global');

        $viewer = User::factory()->create([
            'email_verified_at' => now(),
            'current_team_id' => $organizer->currentTeam->id,
        ]);
        $organizer->currentTeam->users()->attach($viewer, ['role' => $viewerRole->key]);

        app(EventOperationalLockService::class)->lock(
            event: $event,
            key: EventOperationalLockKey::PUBLISH,
            actor: $operator,
            reason: 'Operations review',
        );

        $this->actingAs($viewer->fresh(['currentTeam']))
            ->get(route('admin.events.show', $event->uuid))
            ->assertOk()
            ->assertSee('data-testid="event-operations-lock-panel"', false)
            ->assertSee('data-testid="event-operations-lock-publish-status"', false)
            ->assertSee('Operations review')
            ->assertDontSee('data-testid="event-operations-unlock-publish"', false)
            ->assertDontSee('data-testid="event-operations-lock-go_live-cta"', false)
            ->assertDontSee(__('events.show.operations.reason_label'));
    }

    private function approveCurrentAuditSnapshot(Event $event, User $actor): void
    {
        $request = app(AiAuditRequestService::class)->createOrReuseForEvent($event);
        $request->update(['status' => AiAuditRequestStatus::RESOLVED]);

        AiAuditVerdict::query()->create([
            'ai_audit_request_id' => $request->id,
            'actor_id' => $actor->id,
            'outcome' => AiAuditVerdictOutcome::APPROVE,
            'status' => AiAuditVerdictStatus::CURRENT,
            'decided_at' => now(),
        ]);
    }

    private function createPlatformSuperAdmin(?Team $team = null): User
    {
        $workspace = $team ?? Team::factory()->nonPersonal()->create();
        $user = User::factory()->create([
            'email_verified_at' => now(),
            'current_team_id' => $workspace->id,
        ]);

        $workspace->users()->attach($user, ['role' => UserRole::SYSTEM_ADMIN->value]);

        return $user->fresh(['currentTeam']);
    }
}

